  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Fills tiles with water up to the specified distance from the source using BFS.
   * Algorithm:
   *   1. If distance == 0, do nothing.
   *   2. If this is the first fill (prevFilledDistance == null), call fillBeginTile() to mark source as filled.
   *   3. Perform BFS from the source, expanding outward up to the given distance.
   *   4. For each pipe encountered, check if water can flow from current tile to neighbor:
   *      - Get current pipe's connections.
   *      - For each connection direction, compute neighbor coordinate using Pa19Helper.getOffset.
   *      - If neighbor is within bounds and contains a pipe, check if neighbor pipe's connections include the opposite direction.
   *      - If both conditions match, mark neighbor as filled and add to filledTiles.
   *   5. Update prevFilledDistance to distance.
   *   6. Update prevFilledTiles count for loss detection.
   * Related Features: filledTiles, prevFilledDistance, prevFilledTiles, sourceCell fields
   * Related Classes: Coordinate, TerminationCell, Pipe, Direction, FillableCell, Pa19Helper
   * Input: distance : int - the current water expansion distance from source.
   * Output: void
   * Pre-condition: distance >= 0
   * Post-condition: All reachable pipes within the given distance from source are filled with water; filledTiles list is updated.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (distance == 0) {
      return;
    }

    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();

    if (getPrevFilledDistance() == null) {
      fillBeginTile();
    }

    java.util.Queue<Coordinate> queue = new java.util.LinkedList<Coordinate>();
    java.util.Set<Coordinate> visited = new java.util.HashSet<Coordinate>();

    Coordinate sourceCoord = getSourceCell().getCoord();
    queue.add(sourceCoord);
    visited.add(sourceCoord);

    int currentDist = 0;

    while (!queue.isEmpty() && currentDist < distance) {
      int levelSize = queue.size();
      for (int i = 0; i < levelSize; i++) {
        Coordinate current = queue.poll();
        Cell currentCell = getCell()[current.getRow()][current.getCol()];

        EList<Direction> dirsToExplore = null;

        if (currentCell instanceof FillableCell) {
          Pipe pipe = ((FillableCell) currentCell).getPipe();
          if (pipe != null) {
            dirsToExplore = pipe.getConnections();
          }
        } else if (currentCell instanceof TerminationCell) {
          TerminationCell termCell = (TerminationCell) currentCell;
          if (termCell.isFilled()) {
            dirsToExplore = new BasicEList<Direction>();
            dirsToExplore.add(termCell.getPointingTo());
          }
        }

        if (dirsToExplore != null) {
          for (Direction dir : dirsToExplore) {
            Coordinate offset = helper.getOffset(dir);
            int neighborRow = current.getRow() + offset.getRow();
            int neighborCol = current.getCol() + offset.getCol();

            if (neighborRow >= 0 && neighborRow < getRows() &&
                neighborCol >= 0 && neighborCol < getCols()) {

              Coordinate neighborCoord = Pa19Factory.eINSTANCE.createCoordinate();
              neighborCoord.setRow(neighborRow);
              neighborCoord.setCol(neighborCol);

              if (!visited.contains(neighborCoord)) {
                Cell neighborCell = getCell()[neighborRow][neighborCol];
                Direction opposite = helper.getOpposite(dir);
                boolean canFlow = false;

                if (neighborCell instanceof FillableCell) {
                  Pipe neighborPipe = ((FillableCell) neighborCell).getPipe();
                  if (neighborPipe != null && neighborPipe.getConnections().contains(opposite)) {
                    canFlow = true;
                    neighborPipe.setFilled(true);
                  }
                } else if (neighborCell instanceof TerminationCell) {
                  if (opposite.equals(((TerminationCell) neighborCell).getPointingTo())) {
                    canFlow = true;
                    ((TerminationCell) neighborCell).setFilled(true);
                  }
                }

                if (canFlow) {
                  visited.add(neighborCoord);
                  queue.add(neighborCoord);
                  if (!getFilledTiles().contains(neighborCoord)) {
                    getFilledTiles().add(neighborCoord);
                  }
                }
              }
            }
          }
        }
      }
      currentDist++;
    }

    setPrevFilledTiles(getFilledTiles().size());
    setPrevFilledDistance(distance);
  }

